#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'data/latest.json').read_text(encoding='utf-8')) if (ROOT/'data/latest.json').exists() else {'generated_at':'هنوز اسکن انجام نشده','count':0,'top':[]}
rows=''.join(f"<tr><td>{i}</td><td><a href='{x['url']}' target='_blank' rel='noopener'>{x['full_name']}</a></td><td>{x['stars']:,}</td><td>{x['license'] or 'نامشخص'}</td><td><b>{x['score']}</b></td><td>{x['best_path']}</td></tr>" for i,x in enumerate(data['top'],1))
html=f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="رادار دائمی فرصت‌های درآمدزایی از پروژه‌های متن‌باز گیت‌هاب"><title>رادار فرصت‌های متن‌باز</title><style>*{{box-sizing:border-box}}body{{font-family:Tahoma,"Vazirmatn",system-ui,sans-serif;margin:0;background:#0b1020;color:#e8ecf5;line-height:1.8}}main{{max-width:1250px;margin:auto;padding:28px 20px}}header{{margin-bottom:28px}}h1{{font-size:clamp(26px,4vw,42px);margin:0 0 8px}}h2{{margin-top:30px}}.subtitle{{color:#aab5cc;margin:0}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}}.card{{background:#151c31;padding:20px;border-radius:14px;border:1px solid #26304a}}.card h2{{margin:0;font-size:30px}}.card p{{margin:4px 0 0;color:#aab5cc}}.table-wrap{{overflow-x:auto;border-radius:14px}}table{{width:100%;margin-top:18px;border-collapse:collapse;background:#151c31;min-width:850px}}td,th{{padding:12px;border-bottom:1px solid #2a3552;text-align:right}}th{{color:#b9c5dc;background:#11182a}}a{{color:#8db4ff;text-decoration:none}}a:hover{{text-decoration:underline}}.badge{{display:inline-block;padding:3px 9px;border-radius:999px;background:#202a43;color:#b9c5dc;font-size:13px}}footer{{margin-top:30px;color:#7f8ba5;font-size:13px}}@media(max-width:800px){{.grid{{grid-template-columns:1fr}}main{{padding:20px 14px}}}}@media(prefers-reduced-motion:no-preference){{a{{transition:opacity .15s}}}} </style></head><body><main><header><h1>📡 رادار فرصت‌های متن‌باز</h1><p class="subtitle">کشف پروژه‌های برتر گیت‌هاب، تحلیل رشد و شناسایی فرصت‌های درآمدزایی</p><p class="badge">آخرین به‌روزرسانی: {data['generated_at']}</p></header><section class="grid"><div class="card"><h2>{data['count']}</h2><p>مخزن بررسی‌شده</p></div><div class="card"><h2>{len(data['top'])}</h2><p>فرصت رتبه‌بندی‌شده</p></div><div class="card"><h2>روزانه</h2><p>دوره اسکن خودکار</p></div></section><h2>🏆 برترین فرصت‌های درآمدی</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>پروژه</th><th>ستاره</th><th>مجوز</th><th>امتیاز فرصت</th><th>بهترین مسیر درآمد</th></tr></thead><tbody>{rows}</tbody></table></div><footer>این امتیازها بر اساس داده‌های عمومی و تحلیل خودکار تولید شده‌اند و تضمین درآمد نیستند.</footer></main></body></html>'''
out=ROOT/'dashboard'/'index.html'; out.parent.mkdir(exist_ok=True); out.write_text(html,encoding='utf-8')
